INSERT INTO quizzes (book_id, chapter, kind, title) VALUES (10, 16, 'theory', 'Quiz: borrowing and references');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 0, 'How many readers (&T) can exist at the same time for one value if there are no writers?', '["Exactly one", "Two", "As many as you like", "As many as the processor has cores"]', 2, 'While nobody writes, readers do not get in each other''s way — like several cores holding a cache line in the Shared state. The restriction appears only with a writer.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 1, 'What does the borrow checker do with this code: let first = &v[0]; v.push(4); println!("{first}");?', '["Compiles it: push is always safe", "Compiles it, but panics at run time", "Automatically clones the vector", "Refuses to compile: the borrow first is still needed, and push may move the buffer"]', 3, 'push may allocate a new buffer and free the old one — first would be left hanging in the void. Rust forbids changing the vector while a reader is alive and catches this at build time.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 2, 'Why does the function fn make() -> &String { let s = String::new(); &s } not compile?', '["Because the reference would outlive the function''s frame and the value destroyed in it", "Because a String cannot be created inside a function", "Because you need to write &mut", "Because functions cannot return references"]', 0, 'The frame disappears on return, s is destroyed — the reference would point into a dead zone. The fix: return a String, that is, hand over ownership.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 3, 'What is a slice &str or &[T] made of, and how much does it take on a 64-bit machine?', '["Only a pointer, 8 bytes", "A pointer and a length, 16 bytes", "A copy of the data, the size depends on the slice", "A pointer, a length and a capacity, 24 bytes"]', 1, 'A slice does not own data: it is the address of the start and the number of elements. Only String and Vec, which own a buffer, have a capacity.');
INSERT INTO quiz_questions (book_id, chapter, ord, q, options, answer, expl) VALUES (10, 16, 4, 'What does the lifetime annotation mean in fn longest<''a>(a: &''a str, b: &''a str) -> &''a str?', '["At run time the program checks that the references are still alive", "The function copies the strings for the duration of the call", "The result will not outlive either argument — the compiler checks this, and the annotation does not exist at run time", "The result always points to a"]', 2, 'Lifetime parameters are hints for the borrow checker: they tie references together in the signature and are erased at build time, costing nothing at run time.');
